$pageTitle='Master กิจกรรมย่อย สพฐ.';$pageHeading='Master กิจกรรมย่อย สพฐ. 151-155';$pageDescription='กำหนดชื่อ หน่วยนับ Mapping ฝ่าย และสัดส่วนอ้างอิง โดยรหัส 155 เชื่อมกับกลุ่มบริหารกิจการนักเรียน';$activeMenu='obec-master';require_once __DIR__.'/../includes/bootstrap.php';qa_require_login();qa_require_permission('obec.master');$db=qa_db();$user=qa_current_user();$userId=$user?(int)$user['user_id']:0;$breadcrumbs=array(array('label'=>'ตั้งค่าระบบ','url'=>qa_url('settings/index.php')),array('label'=>'Master กิจกรรมย่อย สพฐ.'));
