<?php if($message): ?><div class="alert <?= $messageType==='danger'?'alert-danger':'alert-success' ?>"><?= h($message) ?></div><?php endif; ?><div class="action-bar"><a class="btn" href="<?= h(qa_url('reports/obec-workload.php')) ?>">← รายงานปริมาณงาน</a></div><div class="card"><div class="section-heading"><div><h2>รหัส 151-155</h2><p>สำหรับโรงเรียนการศึกษาพิเศษ</p></div></div><div class="table-wrap"><table><thead><tr><th>รหัส</th><th>ชื่อ</th><th>หน่วย</th><th>Mapping ฝ่าย</th><th>สัดส่วนอ้างอิง (%)</th><th>สถานะ</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><form method="post"><input type="hidden" name="csrf_token" value="<?= h(qa_csrf_token()) ?>"><input type="hidden" name="subactivity_id" value="<?= h($r['subactivity_id']) ?>"><td><span class="obec-code-badge"><?= h($r['subactivity_code']) ?></span></td><td><input name="subactivity_name" value="<?= h($r['subactivity_name']) ?>"></td><td><input name="unit_name" value="<?= h($r['unit_name']) ?>"></td><td><select name="default_division_id"><option value="0">-- ไม่กำหนด --</option><?php foreach($divisions as $d): ?><option value="<?= h($d['division_id']) ?>" <?= (int)$d['division_id']===(int)$r['default_division_id']?'selected':'' ?>><?= h($d['division_name']) ?></option><?php endforeach; ?></select></td><td><input type="number" min="0" max="100" step="0.01" name="allocation_weight" value="<?= h($r['allocation_weight']) ?>"></td><td><label class="inline-check"><input type="checkbox" name="is_active" value="1" <?= $r['is_active']?'checked':'' ?>> ใช้งาน</label></td><td><button class="btn btn-sm btn-primary">บันทึก</button></td></form></tr><?php endforeach; ?></tbody></table></div></div><div class="notice" style="margin-top:16px"><strong>ข้อควรระวัง:</strong> 40/10/10/5/35 เป็นสัดส่วนอ้างอิงการปันส่วนค่าใช้จ่าย ไม่ใช่สัดส่วนบังคับของงบโรงเรียน</div><?php require QA_ROOT.'/includes/footer.php'; ?>
